import { McpServer } from "@modelcontextprotocol/sdk/server/mcp.js"
import { StdioServerTransport } from "@modelcontextprotocol/sdk/server/stdio.js"
import { Cause, Effect, Exit } from "effect"

class TransportStartupError extends Error {
  readonly _tag = "TransportStartupError"

  constructor(readonly transport: string, readonly reason: unknown) {
    super(`Unable to connect ${transport}: ${String(reason)}`)
  }
}

const createServer = Effect.sync(() => {
  const server = new McpServer({
    name: "workspace-search",
    version: "1.0.0"
  })

  server.registerResource(
    "workspace-info",
    "workspace://info",
    { description: "Current workspace information" },
    async (uri) => ({
      contents: [{ uri: uri.href, text: process.cwd() }]
    })
  )

  return server
})

const start = Effect.gen(function*() {
  const server = yield* createServer
  const transport = yield* Effect.sync(() => new StdioServerTransport())

  yield* Effect.tryPromise({
    try: () => server.connect(transport),
    catch: (reason) => new TransportStartupError("stdio", reason)
  })
})

const exit = await Effect.runPromiseExit(start)

if (Exit.isFailure(exit)) {
  const error = Cause.squash(exit.cause)
  const details = error instanceof TransportStartupError
    ? `${error.transport}: ${String(error.reason)}`
    : "MCP startup failed"
  process.stderr.write(`Workspace MCP could not start:\n${details}\n`)
  process.exitCode = 1
}

